import math

def is_modest(num_str, l, r):
    for i in range(len(num_str)):
        if len(num_str) - i < r - l + 1:
            break
        modest_count = 0
        for j in range(i, len(num_str)):
            if int(num_str[i:j+1]) >= l and int(num_str[i:j+1]) <= r and num_str[i] != '0':
                modest_count += 1
            if num_str[i] != '0':
                break
        if modest_count != (r - l + 1) // (len(num_str) - i):
            return False
    return True

def find_max_modest_substrings(l, r, n):
    max_modest_count = 0
    best_str = ''
    for i in range(1, n + 1):
        substr = f"{i}" * i
        if is_modest(substr, l, r):
            max_modest_count = i
            best_str = substr
    return max_modest_count, best_str

