import math

def fibG(n):
    if n == 0 or n == 1:
        return 1

    a = 1
    b = 1
    for i in range(n):
        a, b = b, a + b

    return b

def findPreSum(arr, query):
    preSum = [0] * (len(arr) + 1)
    for i in range(len(arr)):
        preSum[i + 1] = preSum[i] + arr[i]

    preSumHash = {}
    for i in range(1, len(arr) + 1):
        preSumHash[preSum[i]] = i

    def hashValue(k):
        return fibG(math.floor(math.log(k, 2)))

    neededHash = hashValue(query)
    ans = 0
    for i in range(1, len(arr) + 1):
        if query == preSum[i] and i == preSumHash[neededHash]:
            ans += 1
    return ans

def queryFibG(arr, n):
    preArr = [0] * (n + 1)
    preArr[1] = arr[0]
    for i in range(2, n + 1):
        preArr[i] = preArr[i - 1] + preArr[i - 2]

    preArrHash = {}
    for i in range(1, n + 1):
        preArrHash[preArr[i]] = i

    def hashPreArr(k):
        return fibG(math.floor(math.log(k, 2)))

    neededHash = hashPreArr(n)
    return search(neededHash, n)

def search(target, n):
    if target == 0:
        return 2 ** n
    if target == n:
        return 1
    if n < target and target < 2 * n:
        return 2

    start, end = 1, n
    while start < end:
        mid = start + (end - start) // 2
        if search(target, mid) > search(target, start):
            end = mid
        else:
            start = mid + 1

    if search(target, start) + search(target, start - 1) > search(target, end):
        return search(target, end)
    return search(target, start - 1)

