from collections import defaultdict

class TreeDistance:
    def __init__(self, n):
        self.n = n
        self.parents = defaultdict(list)
        self.distance = defaultdict(lambda: defaultdict(int))

    def add_edge(self, u, v):
        self.parents[v].append(u)

    def update_distance(self, node, parent=None):
        distance[parent] = 0
        queue = [(parent, 0)]
        while queue:
            parent, dist = queue.pop(0)
            if parent:
                self.distance[node][parent] = dist
            queue.extend([(u, dist+1) for u in self.parents[parent]])

    def query(self, start, node, parent=None):
        distance[node][parent] += 1
        for neighbor in self.parents[node]:
            if neighbor != parent:
                update_distance(neighbor, node)

    def harvest_subtree(self, node, parent=None):
        total_distance = 0
        bush_count = 0
        for parent in [p for p in self.parents[node]]:
            if parent != parent:
                bush_count += self.harvest_subtree(parent, node)
                total_distance += self.distance[node][parent]
        return total_distance, bush_count

def solve(n, q, a, p, day_init):
    tree = TreeDistance(n)
    for i in range(1, n):
        tree.add_edge(p[i-1], i)
    for i in range(1, n):
        tree.update_distance(i)
    distances = defaultdict(dict)
    ans = defaultdict(dict)
    for i in range(1, n):
        for x in range(n):
            tree.harvest_subtree(x, i)
            distances[i][x] = tree.distance[i][-1][x]
            ans[i][x] = tree.distance[i][-1][x]
    return [f'{total_distances} {bush_count}' for total_distances, bush_count in ans.items()]

n, q = map(int, input().split())
