import sys

def ask_coffee(i):
    print('? ' + str(i), file=sys.stderr, flush=True)
    sys.stderr.flush()
    return input().strip() == 'Y'

def reset_memory():
    print('R', file=sys.stderr, flush=True)
    sys.stderr.flush()

def ask_memory_left():
    for _ in range(2):  # Asking enough times to ensure memory is reset
        print('? ' + str(ask_coffee(i)), file=sys.stderr, flush=True)
        sys.stderr.flush()
    return ask_coffee(i)

def main():
    n, k = map(int, input().split())

    # Reset memory 1 times before asking the first coffee
    reset_memory()

    # Ask 2*k - 2 agains coffee with the same memory footprint as the question
    coffee_number = 1
    while coffee_number <= k:
        coffee_number += 1
        while True:
            if ask_coffee(coffee_number) != ask_memory_left():
                print(f'! {coffee_number - 1}', file=sys.stderr, flush=True)
                sys.stderr.flush()
                return
            if coffee_number > k:
                coffee_number = ask_memory_left() + 1

if __name__ == "__main__":
