            return start, 0, states
        memo[start] = end
        return start, 1, states
    mini, length = states + 1, states + 1
    for i in range(states):
        if memo[path[i]]:
            k, l = dfs(memo[path[i]], end, path[:i] + path[i:i + 1] + path[i + 1:], memo)
