        while root_u != root_v:
            value_at_level[root_v] += pow(2, l - 1 - int(log2(abs(root_u - root_v) + 1))) if value_at_level[root_v] + pow(
                2, l - 1 - int(log2(abs(root_u - root_v) + 1))) > m[root_u, root_v] else m[root_u, root_v] - m[root_v, root_u]
