from collections import defaultdict, deque, Counter
from heapq import heappush, heappop
from math import sqrt

def dijkstra(graph, start, end):
    n = len(graph)
    dist = [float('inf')] * n
    dist[start] = 0
    pq = [(0, start)]

    while pq:
        current_dist, current_node = heappop(pq)
        if current_dist > dist[current_node]:
            continue
        for neighbor, weight in graph[current_node]:
            new_dist = current_dist + weight
            if new_dist < dist[neighbor]:
                dist[neighbor] = new_dist
                heappush(pq, (new_dist, neighbor))

    min_distance = float('inf')
    for i in range(1, n):
        if dist[i] < float('inf') and dist[i] < min_distance:
            min_distance = dist[i]
    return min_distance

def minimum_capacity(edges, centrals, missions):
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    results = []
    for start, end in missions:
        if start == end:
            results.append(0)
            continue
        central_map = {central: dijkstra(graph, 1, central) for central in centrals}
        min_central = min((central, central_map[central]) for central in centrals)
        g = graph.copy()
        for center, distance in central_map.items():
            if distance >= g[start][center]:
                g[start][center] = distance
                g[center][start] = distance
        distances = {start: 0, end: 0}
        heap = [(0, start)]
        while heap:
            current_dist, current_node = heappop(heap)
            if current_node == start:
                distances[start] = current_dist
                continue
            for neighbor, weight in g[current_node]:
                new_dist = distances[current_node] + weight
                if new_dist < distances[neighbor]:
                    distances[neighbor] = new_dist
                    heappush(heap, (new_dist, neighbor))
                    if distances[neighbor] >= 1000000:
                        heappop(heap)
                        heappush(heap, (distances[neighbor], neighbor))
        results.append(distances[end])

    return results

