from collections import defaultdict

def find_ceo_size(n, json_list):
    root_odd = 0
    root_even = 0
    root_odd_odd = 0
    root_odd_even = 0
    root_even_odd = 0
    root_even_even = 0

    for jsonObj in reversed(json_list):
        id = jsonObj[0]
        rank = jsonObj[1]
        if id == 0:
            root_odd += 1
        else:
            parent_id[root_odd] = parent_id[root_odd - 1]
            parent_id[root_odd_even + (root_odd & 1)] += 1
            root_odd_even += (root_odd & 1)

    def find(x):
        if x != parent_id[x]:
            parent_id[x] = find(parent_id[x])
        return parent_id[x]

    def union(x, y):
        root_x = find(x)
        root_y = find(y)
        if root_x < root_y:
            parent_id[root_x] = root_y
        else:
            parent_id[root_y] = root_x

    def block(x):
        while x != parent_id[x]:
            x = parent_id[x]
        return x

    parent_id = dict(zip(range(root_odd + 1), range(root_odd + 1)))
    if root_odd % 2 == 0:
        parent_id[0] = block(root_odd_even + 0)
    else:
        parent_id[0] = block(root_odd_even + 1)

    depart_pro = defaultdict(list)

    for i in range(root_odd):
        depart_pro[find(i)].append(i)

    depart_pro[root_odd] = []
    depart_pro[block(root_odd_even + 0)] = []

    def get_r(root, json_list):
        nonlocal root_even
        da_1, da_2 = 0, 0
        if root == 0:
            return da_1, da_2
        for jsonObj in reversed(json_list[root_odd + 1:]):
            if jsonObj[0] == 0:
                parent = jsonObj[0]
                rank_max = jsonObj[1]
                delega = depart_pro[parent]
                for aa in delega:
                    rank_min = rank_max - (rank_min := depart_pro[aa][1]) + 1
                    if rank_min <= rank:
                        da_1 += 1
                    if rank_min <= rank - 1:
                        da_2 += 1
                da_1, da_2 = max(da_1, da_2), min(da_1, da_2)
        return da_1, da_2

    find(block(root_odd_even + 1))
    depart_pro[find(block(root_odd_even + 1))].append(root_odd)
    depart_pro[block(root_odd_even + 0)].extend(
        [block(i) for i in list(range(root_odd, len(json_list))) if find(i) != block(root_odd_even + 0) and block(i) != find(block(root_odd_even + 1))])
    depart_pro.find(block(root_odd_even + 0))

    ret = [0 for _ in range(n)]
    for i, root in enumerate(depart_pro):
        answer, replace = get_r(root, json_list)
        ret[i] = replace + answer

    return ret

