    root = 0
    stack = [root]
    curr = 0
    while stack:
        node = stack.pop()
        restartPi = 0
        for nei in map[node]:
            restartPi = max(restartPi, restartPi(nei))
        restartPi = max(restartPi, restartPi + 1)
        map[node] = restartPi
        for nei in map[node]:
            if map[nei] == 0:
                continue
            stack.append(nei)
            curr = max(curr, restartPi)
    return curr

