    return total_subordinates

def negligibility(rank, managers):
    total_negligibility = replaceability(rank, managers)
    for manager in managers:
        if manager != 0 and rank > managers[manager] - 1:
            return 'error'  # Management hierarchy violated
        total_negligibility += replaceability(rank - 1, managers[:manager]) + replaceability(rank, managers[manager:1])
    return total_negligibility

