                    if b2 < 2 * b1:
                        y, x = x, 1
                if b1 + (b2 - 1) > total_inversions:
                    q = (1 + b1 + b2) // 2
                    x = q
                    y, x = x, 2 ** max(q - 1, 0)

                break
        else:
            return str(-1)

    if x != 1 and y != 1:
        return str(-1)

    if strange_solutions:
        return "Use Standard Input format"

    allowed_ops = []
    insertion_point = 0
    for i in range(4):
        inversions = b1[j + 1] - b1[j] for j in range(4) if j != i
        if not j:
            forward_number = b1[i] - (b1[i] + inversions) // 2 + (inversions % 2) * (x + 1) // 2
            backward_number = b1[i] - (b1[i] - inversions) // 2 + (inversions % 2) * (x - 1) // 2
            if forward_number < (x + 1) // 2:
                allowed_ops.insert(insertion_point, (x + 1) // 2)
                insertion_point += 1
            elif backward_number > (x - 1) // 2:
                allowed_ops.insert(insertion_point, (x - 1) // 2)
                insertion_point += 1

    return str(len(allowed_ops)), '\n'.join(map(str, allowed_ops))

