from collections import defaultdict

def calculate_feedback(n, employees_hierarchy):
    # Initialize the feedback list
    feedback = [0] * (n+2)

    # Transform the graph hierarchy
    for i in range(1, n+1):
        if employees_hierarchy[i] == i-1:
            employees_hierarchy[i] = 0

    # Union-find operations
    def find(x):
        feedback[x] += 1
        if x != feedback[x]:
            feedback[x] = find(feedback[x])
        return feedback[x]

    parent, rank = [i for i in range(n+2)], [0 for _ in range(n+2)]

    def union(x, y):
        rootX, rootY = find(x), find(y)
        if rootX != rootY:
            if rank[rootX] > rank[rootY]:
                rootX, rootY = rootY, rootX
            feedback[rootX] += feedback[rootY]
            feedback[rootY] = rootX
            if rank[rootX] == rank[rootY]:
                rank[rootX] += 1

    # Union every manager-related chain of employees
    for manager in employees_hierarchy[0]:
        for employee in range(manager+1, n+1):
            union(employee, manager)

    # Calculate the rank of each manager related to an employee
    student_rank = [0] * (n+1)
    for parent in range(1, n+1):
        rank, students = [0], [parent]
        while parent in parent:
            rank.append(feedback[parent])
            students.append(parent)
            parent = feedback[parent]
        # Transform the rank input to actual employees
        for student in students:
            if student in parent:
                student = parent
        student_rank[student] = sum(rank) - sum(student_rank[rank[i] for i in student - range(manager)])

    # Calculate the feedback list
    for student in range(1, n+1):
        feedback[student_rank[student]] = student_rank[student]

    return feedback[1:]

# Example cases
print(calculate_feedback(4, [0, 1, 2, 1]))
print(calculate_feedback(5, [2, 3, 4, 5, 0]))
print(calculate_feedback(5, [0, 1, 1, 1, 3]))
