def is_ceo(manager_id, n):
    return manager_id == 0

def rank(subordinate, manager):
    return manager + 1

def replaceability(manager_id, n, employees):
    total_replaces = manager_id - 1
    replaces_of_manager = 0
    is_first = True
    for subordinate in range(manager_id, n):
        if is_ceo(employees[subordinate], n) or subordinate == n - 1:
            is_first = False
            break
        if rank(subordinate, employees[manager_id]) <= employees[subordinate]:
            replaces_of_manager += 1
    total_replaces += replaces_of_manager if is_first else replaces_of_manager - 1
    return total_replaces

def negligibility(employees, n):
    replaces = {}
    max_items = {}
    for employee_id in range(1, n):
        mng_id = employees[employee_id]
        replaces[employee_id] = replaceability(employee_id, n, employees)
        if mng_id in max_items:
            max_items[mng_id] = max(max_items[mng_id], replaces[employee_id])
        else:
            max_items[mng_id] = replaces[employee_id]

    negligibility = 0
    for subordinate in range(1, n):
        sub_id = employees[subordinate]
        mng_id = employees[sub_id]
        z = 0
        for i in range(subordinate, n):
            if employees[i] == mng_id:
                z += max_items[i]
                break
        negligibility += z
        max_items[mng_id] = max(max_items[mng_id], z)

    return negligibility

