from typing import List

def min_fire_balls(n: int, a: int, b: int, h: List[int]) -> int:
    """
    Finds the minimum number of fire balls needed to kill all archers in the game.
    """
    min_balls = 0
    archer_count = 0

    for i in range(1, n-1):
        if h[i] > 0:
            min_balls += 1
            archer_count += 1
            min_balls += h[i] // a + (h[i] % a != 0)

    return archer_count + min_balls

def find_archers_to_hit(n: int, a: int, b: int, h: List[int], archer_map: List[List[int]]) -> List[int]:
    """
    Returns a list of archer indices to hit in order to kill all archers.
    """
    archer_count_by_index = {}
    for index, archer in enumerate(archer_map):
        archer_count_by_index[index] = max(archer.count(0), archer.count(b-1))

    archers_to_hit = set()
    for i in range(n-1):
        if archer_count_by_index[archer_map[i][0]] > archer_count_by_index[archer_map[i+1][0]]:
            archers_to_hit.add(i+1)
        elif archer_count_by_index[archer_map[i][0]] == archer_count_by_index[archer_map[i+1][0]]:
            archers_to_hit.add(i+1)
        elif archer_count_by_index[archer_map[i][0]] < archer_count_by_index[archer_map[i+1][0]]:
            archers_to_hit.add(i+1)

    return list(archers_to_hit)

