import math
from functools import partial
from collections import defaultdict

def compute_f(x, i, m, y, A):
    # Helper function to compute F(i, m) in logarithmic time
    return A[:, i] ** (m - math.floor(math.log(m, 2)))

def query_answer(m, y, A):
    max_log = math.floor(math.log(y, 2)) + 1
    dp = defaultdict(list)

    for i in range(N):
        key = m, i
        value = compute_f(i, i, m, y, A).sum()
        dp[max_log].append((key, value))

    for log in range(max_log - 1, -1, -1):
        keys = dp[log + 1]
        for key, val in keys:
            i, i_m = key
            if val < y:
                dp[log].append((key, val + A[i, i_m]))
            elif val > y:
                dp[log].remove((key, val))

    return dp[log - 1]


