import math

def is_modest(num_str):
    if len(num_str) == 1:
        return True
    last_digit = int(num_str[0])
    for i in range(1, len(num_str)):
        current_digit = int(num_str[i])
        if abs(last_digit - current_digit) > 1:
            return False
        last_digit = current_digit
    return True

def count_modest_substrings(s):
    stck = [-1]
    for i, d in enumerate(s):
        if stck[-1] + 1 != int(d):
            stck.append(i)
    stck.pop()
    sts = [i for i in stck if i > -1]
    return sum(abs(x - i) for i, x in enumerate(sts))

l, r, n = map(int, input().split())
