def factorial(n):
    result = 1
    for i in range(2, n + 1):
        result = (result * i) % (10 ** 9 + 7)
    return result

def find_perfect_sets(k):
    mod = 10 ** 9 + 7
    if k == 0:
        return 1
    if k == 1:
        return 2
    if k == 2:
        return 3
    if k == 3:
        return 5
    elif k == 4:
        return 6

    power_of_two = 1
    for i in range(2, 8):
        if 2 ** i > k:
            power_of_two = power_of_two * i
    for i in range(8, 15):
        if 2 ** i > k:
            power_of_two = power_of_two * i

    return factorial(k + 1) * (power_of_two + 1) // 2 % mod

k = int(input().strip())
print(find_perfect_sets(k))
